import pathlib,json,hashlib,collections,datetime
from fractions import Fraction
P=pathlib.Path(__file__).resolve().parent
h=lambda b:hashlib.sha256(b).hexdigest()
def write(n,d):(P/n).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
rows={int(s.split('\t')[0]):s.rstrip('\n').split('\t')[1:] for s in (P/'reviews.tsv').read_text().splitlines()}
a=[]
sel={395263:('ems2053.txt',1785,1805,'Theorem 1 states the exact uniform alternative; selected statement and surrounding discussion, not full proof.'),395517:('ems3388.txt',600,640,'Definition of fully Hilbertian and Theorem 2 explicitly give this function-field result; no full proof audited.'),395519:('ems3388.txt',1088,1100,'Conjecture 1 and claimed n=2 consequence read; extracted product/difference notation is defective and does not safely settle the intended coordinate scope.'),395339:('ems2091.txt',1570,1598,'Equation (0.2) is the exact sum and the report explicitly says Mortenson proved it; cited independent proof body not read.')}
for x in json.loads((P/'literal-records.json').read_text()):
 r=x['record'];id=r['mathdb_id'];c,reason,assessment=rows[id]
 d={'mathdb_id':id,'corpus_chunk':x['corpus_chunk'],'corpus_line':x['corpus_line'],'statement_utf8':r['statement'],'statement_sha256':h(r['statement'].encode()),'canonical_record_sha256':x['canonical_record_sha256'],'classification':c,'classification_reason_and_quantifiers':reason,'complete_mathematical_statement_reviewed':c=='complete','technical_assessment':assessment,'disposition':'PARK_NO_BOUNDED_FULL_SCOPE_ROUTE' if c=='complete' else 'HOLD_SCOPE_RESTORATION','source_url':r['source_url'],'source_name':r['source_name'],'source_coverage':{'literal':True,'selected_primary_passage':False,'whole_body':False,'local_proof':False,'full_dependency':False,'successor_body':False,'current_registry':False},'accepted_credit':0,'current_registry_cleared':False}
 if id in sel:
  file,lo,hi,note=sel[id];d['source_coverage']['selected_primary_passage']=True;d['primary_passage']={'file':file,'start_line':lo,'end_line':hi,'note':note}
  d['disposition']={395263:'EXCLUDE_SOURCE_STATED_THEOREM',395517:'EXCLUDE_SOURCE_STATED_THEOREM',395519:'EXCLUDE_WORDING_ONLY_COUNTEREXAMPLE',395339:'HOLD_REPORTED_PUBLIC_PROOF_NOT_AUDITED'}[id]
 a.append(d)
assert len(a)==len(rows)==50
write('dispositions.json',a);write('proposals.json',[])
checks=[]
for p in range(3,98,2):
 if any(p%q==0 for q in range(2,int(p**.5)+1)):continue
 s=Fraction();t=Fraction(1)
 for n in range(p):
  if n:t*=Fraction(2*n-1,2*n)**3
  s+=t*(4*n+1)*(-1)**n
 mod=p**3;v=s.numerator*pow(s.denominator,-1,mod)%mod;rhs=((-1)**((p-1)//2)*p)%mod
 assert v==rhs;checks.append({'p':p,'residue':v,'rhs':rhs})
write('bounded-checks.json',{'395339':{'executed':True,'method':'Exact Fraction recurrence, reduction using denominator inverse modulo p^3','primes':checks,'limit':'Finite checks are neither all-prime proof nor novelty clearance.'},'395519':{'executed':'symbolic deduction only; no CAS claim','witness':'n=2, V={x1=0}; Q-points dense in affine line, no point has nonintegral x1','credit':0,'limit':'Literal wording failure; intended source notation and dominance hypotheses not restored.'}})
write('source-coverage.json',{'reviewed_literal_records':50,'primary_selected_records':list(sel),'reports_downloaded':3,'whole_reports_read':0,'proof_bodies_audited':0,'successor_bodies_read':0,'current_registry':'HOLD unavailable; no absence-of-hits inference','coverage_limit':'Four selected primary passages, not whole-report, dependency or novelty clearance. No substantial hypothesis investment undertaken.'})
write('failures.json',{'new_http_failures':[],'stopped_routes_preserved':['MathDB 429: zero requests','author Gorenstein PDF TLS r642','AIM/Kourovka/EGRES/AIProofWatch','DMGT TLS','ProjectEuclid challenge','ResearchGate 403','OEIS A274199/internal 403 r542','DOI10.1093/imrn/rnz305 OUP Cloudflare403 r618'],'gates':['Current registry unavailable: HOLD','Successor and full dependency bodies unread: HOLD','No proof, Lean, manuscript or credit changes'],'deviations':['Initial passage extraction emitted repetitive context and adjacent report text beyond the selected passages; this is not credited as scientific review. The extracted TXT bytes were bound before search. Passage JSON excerpts were not individually bound before initial tool emission; final manifest binds them, without retroactive pre-read compliance claim.'],'source_scope_failure':'395519 PDF text product/difference expression corrupted; no visual reconstruction attempted; wording-only objection excluded from credit.'})
c=collections.Counter(d['classification'] for d in a)
(P/'SUMMARY.md').write_text('''# Sol breadth r648\n\nReviewed all 50 assigned literal records without replacement. Independent classifications: '''+', '.join(f'{v} {k}' for k,v in sorted(c.items()))+'''. Baseline 7,083; these are 50 additional disjoint literal reviews (7,133 if root reconciles), not full technical corpus coverage. Zero proposals and zero credit; counts remain 9 additional / 39 total / next 40.\n\nFour selected primary passages in three dated Oberwolfach reports were read: 395263 is explicitly Theorem 1 (strong Tits); 395517 is explicitly Theorem 2 (fully Hilbertian function fields); 395339 is Equation (0.2), explicitly reported proved by Mortenson, with cited proof unread; 395519 has a trivial coordinate-hyperplane failure in the literal and defective extracted source notation, so no discovery credit. No whole-report or successor-proof audit is claimed. Exact finite supercongruence checks cover odd primes through 97, not all primes.\n\nOther records receive individual technical objections with quantifiers and scope reasons in dispositions.json. Missing definitions and incomplete data are retained. No hard target was ground through repeated sweeps. Current-registry, successor-body, proof, formal and novelty gates remain HOLD. No focused hypothesis is recommended.\n\nThe intake exact payload, direct original/copy pairs, original 20 corpus chunks and 8 frozen inputs were independently checked in place. Three reservation sets are disjoint from each other, protected IDs and 7,083 coverage entries. Flat bindings reference originals; no corpus or historical trees copied. Upstream verify.py was read but never executed. r304 exclusions, r363 Cayley decision and current adjudications remain operative. 338366 stays excluded with text/figure reconstruction and unread-journal caveats; 338408 stays parked. Sol r644 and held Claude r628 are untouched.\n\nZero MathDB requests, no browser/API-bypass routes, no new HTTP failures. Existing stopped routes remain stopped. Passage-extraction overbreadth and excerpt-binding timing are disclosed in failures.json. All Python and extraction subprocesses ran under the fixed helper guard with unchanged caps.\n\nRun `bash verify.sh` from this directory. The verifier is read-only and checks exact payload, originals, corpus identity, statement/canonical hashes and disjointness; bounded negative checks reject hash, size and extra-file mismatches without changing originals. Integrity PASS is not mathematical or novelty PASS.\n''')
print(dict(c))
